package com.mindarray;

import com.mindarray.eventbus.*;
import com.mindarray.log.*;
import com.mindarray.nms.DiscoveryEngine;
import com.mindarray.nms.MetricPoller;
import com.mindarray.nms.RediscoverEngine;
import com.mindarray.nms.TopologyEngine;
import com.mindarray.plugin.PluginEngine;
import com.mindarray.plugin.PluginEngineResponseProcessor;
import com.mindarray.util.*;
import io.vertx.core.CompositeFuture;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;

public class BootstrapLogCollector
{
    private static final Logger LOGGER = new Logger(BootstrapLogCollector.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Log Collector");

    private static void startRemoteEventProcessor()
    {
        Bootstrap.startEngine(new RemoteEventChangeNotificationHandler(), RemoteEventChangeNotificationHandler.class.getSimpleName(), null)
                .onComplete(response ->
                {
                    if (response.succeeded())
                    {
                        var futures = new ArrayList<Future>();

                        var forwarderPort = CommonUtil.getEventPublisherPort();

                        for (var index = 0; index < MotadataConfigUtil.getEventPublishers(); index++)
                        {
                            var promise = Promise.promise();

                            futures.add(promise.future());

                            Bootstrap.startEngine(new RemoteEventForwarder(forwarderPort + index), RemoteEventForwarder.class.getSimpleName() + " " + (forwarderPort + index), null).onComplete(handler ->
                            {
                                if (handler.succeeded())
                                {
                                    promise.complete();
                                }
                                else
                                {
                                    promise.fail(handler.cause());
                                }
                            });
                        }

                        CompositeFuture.join(futures).onComplete(handler ->
                        {
                            if (handler.succeeded())
                            {
                                try
                                {
                                    EventBusConstants.setRemoteEventProcessorRegistrationId();

                                    EventBusConstants.register(new CipherUtil());

                                    //need to start this engine after RPE register

                                    var asyncResults = new ArrayList<Future>();

                                    var subscriberPort = CommonUtil.getEventSubscriberPort();

                                    for (var index = 0; index < MotadataConfigUtil.getEventSubscribers(); index++)
                                    {
                                        var promise = Promise.promise();

                                        asyncResults.add(promise.future());

                                        Bootstrap.startEngine(new RemoteEventSubscriber(subscriberPort + index), RemoteEventSubscriber.class.getSimpleName() + " " + (subscriberPort + index), null).onComplete(asyncResult ->
                                        {
                                            if (asyncResult.succeeded())
                                            {
                                                promise.complete();
                                            }
                                            else
                                            {
                                                promise.fail(asyncResult.cause());
                                            }
                                        });
                                    }
                                    CompositeFuture.join(asyncResults).compose(future -> Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_LOG_PROCESS, EventBusConstants.EVENT_SOURCE, MotadataConfigUtil.getLogParsers(), LogParser.class.getCanonicalName(), true), LogParser.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new TCPLogListener(), TCPLogListener.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new UDPLogListener(), UDPLogListener.class.getSimpleName(), null))
                                            .onComplete(result ->
                                            {
                                                if (result.failed())
                                                {
                                                    Bootstrap.stop(result.cause());
                                                }
                                                else
                                                {
                                                    LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.bootstrapType()));
                                                }
                                            });
                                }
                                catch (Exception exception)
                                {
                                    Bootstrap.stop(exception);
                                }
                            }
                            else
                            {
                                Bootstrap.stop(handler.cause());
                            }
                        });
                    }
                    else
                    {
                        Bootstrap.stop(response.cause());
                    }
                });
    }

    /*
     *   Port details for Agent/RemoteEventProcessor:
     *
     *   event.publisher.port : start from 9449
     *   event.subscriber.port :start from 9444
     * */

    public void start()
    {
        try
        {
            Bootstrap.logSystemConfig();

            PortUtil.init();

            WebClientUtil.init();

            MotadataConfigUtil.loadConfigs(new JsonObject(Files.readString(new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + "motadata.json").toPath(), StandardCharsets.UTF_8)));

            ProcessUtil.setProcessors();

            startRemoteEventProcessor();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

